class Solution {
    public String reverseStr(String s,int k){
        char[] chars=s.toCharArray();
        for(int start=0;start<chars.length;start+=2*k)for(int left=start,right=Math.min(start+k-1,chars.length-1);left<right;left++,right--){
            char value=chars[left];
            chars[left]=chars[right];
            chars[right]=value;
        }
        return new String(chars);
    }
}

code.kotlin:
class Solution {
    fun reverseStr(s:String,k:Int):String{
        val chars=s.toCharArray();
        var start=0;
        while(start<chars.size){
            var left=start;
            var right=minOf(start+k-1,chars.lastIndex);
            while(left<right){
                val value=chars[left];
                chars[left++]=chars[right];
                chars[right--]=value
            };
            start+=2*k
        };
        return String(chars)
    }
}

